-- Expanded Psionics Handbook powers F.
WITH desired(slug,name,discipline,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,description,augmentation_text) AS (VALUES
('fabricate-psionic','Fabricate, Psionic','metacreativity','creation','See spell text','other','Close (25 ft. + 5 ft./2 levels)','Up to 10 cu. ft./level; see spell text',NULL,NULL,'Instantaneous',NULL,'None','no',NULL,7,'Fabricate raw material into finished goods as the fabricate spell.',NULL),
('fabricate-greater-psionic','Fabricate, Greater Psionic','metacreativity','creation','See spell text','other','Close (25 ft. + 5 ft./2 levels)','Up to 100 cu. ft./level',NULL,NULL,'Instantaneous',NULL,'None','no',NULL,11,'As psionic fabricate, but affects ten times as much material.',NULL),
('false-sensory-input','False Sensory Input','telepathy',NULL,'1 round','full_round','Long (400 ft. + 40 ft./level)','One creature',NULL,NULL,'Concentration, up to 1 min./level (D)','will','Will negates','yes',NULL,5,'Falsify the specifics reported by one of the subject’s senses, switching which sense is altered from round to round.','For every 2 additional PP, affect one additional target within the stated spacing.'),
('far-hand','Far Hand','psychokinesis',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One nonmagical unattended object up to 5 lb.',NULL,NULL,'Concentration, up to 1 min.',NULL,'None','no',NULL,1,'Telekinetically lift and move a small unattended object up to 15 feet per move action.','Additional PP can increase range and object weight limit.'),
('fate-link','Fate Link','clairsentience',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','Two living creatures initially no more than 30 ft. apart',NULL,NULL,'10 min./level','will','Will negates','yes',NULL,5,'Link two creatures so hit point and nonlethal damage suffered by one is mirrored by the other, with a death consequence.','For every 2 additional PP, increase save DC by 1.'),
('fate-of-one','Fate of One','clairsentience',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,13,'Immediately reroll one saving throw, attack roll, or skill check and accept the new result.',NULL),
('feat-leech','Feat Leech','clairsentience',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'1 min./level','will','Will negates; see text','yes',NULL,3,'Temporarily borrow a number of the target’s psionic or metapsionic feats that you qualify to use while denying those feats to the target.','For every 2 additional PP, increase save DC by 1.'),
('fiery-discorporation','Fiery Discorporation','psychokinesis',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'Instantaneous and up to one day; see text',NULL,NULL,'no',NULL,9,'When near an open flame and reduced to 0 or fewer hit points, attempt to discorporate into fire and re-form one day later instead of dying.','For every 3 additional PP, gain +1 on the Will save to discorporate.'),
('fission','Fission','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,'Duplicate of yourself','1 round/level (D)',NULL,NULL,'no',NULL,13,'Create a lower-level duplicate of yourself, splitting power points and limited-use resources until the duplicate rejoins you or dies.',NULL),
('float','Float','psychoportation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'no',NULL,1,'Mentally support yourself in liquid, gaining or increasing swim speed by 10 feet.',NULL),
('fly-psionic','Fly, Psionic','psychoportation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,7,'Fly as the fly spell.',NULL),
('force-screen','Force Screen','psychokinesis',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'no',NULL,1,'Create a mobile force disk that grants a +4 shield bonus to Armor Class, including against incorporeal touch attacks.','For every 4 additional PP, improve the shield bonus by 1.'),
('form-of-doom','Form of Doom','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'no',NULL,11,'Transform into a terrifying combat form with natural armor, DR, Strength and movement bonuses, frightful presence, and four tentacle attacks.','Each additional PP increases duration by 2 rounds.'),
('freedom-of-movement-psionic','Freedom of Movement, Psionic','psychoportation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,7,'Gain freedom of movement as the spell.',NULL),
('fuse-flesh','Fuse Flesh','psychometabolism',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'1 round/level','fort','Fortitude negates and Fortitude partial; see text','yes',NULL,11,'Fuse a creature’s flesh into a helpless configuration and potentially blind, deafen, and suppress many special abilities.','For every 2 additional PP, increase save DC by 1.'),
('fusion','Fusion','psychometabolism',NULL,'1 round','full_round','Touch','You and one touched willing corporeal living creature of your type and size or smaller',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,15,'Fuse with a willing creature, pooling hit points, powers, power points, spells, feats, racial abilities, and class features while using the better relevant statistics.','XP cost 50 XP.')
)
INSERT INTO dnd35_powers
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,augmentation_text,augmentation)
SELECT 'xph-power-'||d.slug,'xph-3.5','Chapter 5',d.slug,d.name,d.description,d.description,0,NULL,1,'xph-power-discipline-'||d.discipline,d.subdiscipline,d.manifesting_time,d.action_type,d.range_text,d.target_text,d.area_text,d.effect_text,d.duration_text,d.save,d.saving_throw_text,d.power_resistance,d.power_resistance_text,d.power_points,d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_powers p WHERE p.slug=d.slug AND p.owner_user_id IS NULL);
